field.eval:
{
    'nodes': [{
        'id': 't0-bags',
        'name': 'T0 Constraints',
        'type': 'decisionTable',
        'content': {
            'hitPolicy': 'collect',
            'inputs': [
                {'id': 'bag_type',       'name': 'bag_type'},
                {'id': 'has_tie',        'name': 'has_tie'},
                {'id': 'packaging_type', 'name': 'packaging_type'}
            ],
            'outputs': [
                {'id': 'level',                 'name': 'level'},
                {'id': 'message',               'name': 'message'},
                {'id': 'packaging_product_ref', 'name': 'packaging_product_ref'}
            ],
            'rules': [
                {
                    'bag_type': '"sheet"',
                    'has_tie':  'true',
                    'packaging_type': '',
                    'level':    '"warning"',
                    'message':  '"Sheet bag with tie: splitting skipped."',
                    'packaging_product_ref': ''
                },
                {
                    'bag_type': '',
                    'has_tie':  '',
                    'packaging_type': '"tray"',
                    'level':    '',
                    'message':  '',
                    'packaging_product_ref': '"mrp_design_matrix_bags.product_packaging_tray"'
                },
                {
                    'bag_type': '',
                    'has_tie':  '',
                    'packaging_type': '"box"',
                    'level':    '',
                    'message':  '',
                    'packaging_product_ref': '"mrp_design_matrix_bags.product_packaging_box"'
                }
            ]
        }
    }]
}

{
    'nodes': [{
        'id': 't0-bags-ext',
        'name': 'T0 Constraints',
        'type': 'decisionTable',
        'content': {
            'hitPolicy': 'collect',
            'inputs': [
                {'id': 'width',             'name': 'width'},
                {'id': 'height',            'name': 'height'},
                {'id': 'thickness',         'name': 'thickness'},
                {'id': 'density',           'name': 'density'},
                {'id': 'construction_type', 'name': 'construction_type'},
                {'id': 'gusset_depth',      'name': 'gusset_depth'}
            ],
            'outputs': [
                {'id': 'level',   'name': 'level'},
                {'id': 'message', 'name': 'message'}
            ],
            'rules': [
                {
                    'width': '0', 'height': '', 'thickness': '',
                    'density': '', 'construction_type': '', 'gusset_depth': '',
                    'level': '"error"',
                    'message': '"Bag width must be greater than 0 mm."'
                },
                {
                    'width': '', 'height': '0', 'thickness': '',
                    'density': '', 'construction_type': '', 'gusset_depth': '',
                    'level': '"error"',
                    'message': '"Bag height (length) must be greater than 0 mm."'
                },
                {
                    'width': '', 'height': '', 'thickness': '0',
                    'density': '', 'construction_type': '', 'gusset_depth': '',
                    'level': '"error"',
                    'message': '"Bag thickness must be greater than 0 mm."'
                },
                {
                    'width': '', 'height': '', 'thickness': '',
                    'density': '0', 'construction_type': '', 'gusset_depth': '',
                    'level': '"error"',
                    'message': '"Material density must be set (g/cm3)."'
                },
                {
                    'width': '', 'height': '', 'thickness': '',
                    'density': '', 'construction_type': '"gusseted"', 'gusset_depth': '0',
                    'level': '"error"',
                    'message': '"Gusseted bag requires gusset depth > 0 mm."'
                },
                {
                    'width': '', 'height': '', 'thickness': '',
                    'density': '', 'construction_type': '"split"', 'gusset_depth': '',
                    'level': '"warning"',
                    'message': '"Split/drawtape bag: verify cord_fold and cord_length are set."'
                }
            ]
        }
    }]
}

{
    'nodes': [
        {'id': 'zen_input', 'type': 'inputNode', 'name': 'Input'},

        {
            'id': 't1a-width',
            'name': 'T1a Material Width',
            'type': 'decisionTable',
            'content': {
                'hitPolicy': 'first',
                'inputs': [
                    {'id': 'construction_type', 'name': 'construction_type'},
                    {'id': 'gusset_mode',       'name': 'gusset_mode'}
                ],
                'outputs': [
                    {'id': 'material_width_mm', 'name': 'material_width_mm'},
                    {'id': 'layers',            'name': 'layers'}
                ],
                'rules': [
                    {
                        'construction_type': '"tube"',
                        'gusset_mode': '',
                        'material_width_mm': 'width * 2',
                        'layers': '2'
                    },
                    {
                        'construction_type': '"gusseted"',
                        'gusset_mode': '"single"',
                        'material_width_mm': '2 * (width + gusset_depth)',
                        'layers': '2'
                    },
                    {
                        'construction_type': '"gusseted"',
                        'gusset_mode': '"double"',
                        'material_width_mm': '2 * (width + 2 * gusset_depth)',
                        'layers': '2'
                    },
                    {
                        'construction_type': '"gusseted"',
                        'gusset_mode': '"none"',
                        'material_width_mm': '2 * width',
                        'layers': '2'
                    },
                    {
                        'construction_type': '"gusseted"',
                        'gusset_mode': '',
                        'material_width_mm': '2 * (width + gusset_depth)',
                        'layers': '2'
                    },
                    {
                        'construction_type': '"split"',
                        'gusset_mode': '',
                        'material_width_mm': 'width * 2 + cord_fold',
                        'layers': '1'
                    },
                    {
                        'construction_type': '"cast"',
                        'gusset_mode': '',
                        'material_width_mm': 'width',
                        'layers': '1'
                    },
                    {
                        'construction_type': '',
                        'gusset_mode': '',
                        'material_width_mm': 'width * 2',
                        'layers': '2'
                    }
                ]
            }
        },

        {
            'id': 't1b-weight',
            'name': 'T1b Bag Weight',
            'type': 'decisionTable',
            'content': {
                'hitPolicy': 'first',
                'inputs': [
                    {'id': 'has_tie', 'name': 'has_tie'}
                ],
                'outputs': [
                    {'id': 'bag_weight_g', 'name': 'bag_weight_g'}
                ],
                'rules': [
                    {
                        'has_tie': 'false',
                        'bag_weight_g': 'material_width_mm * height * thickness * density / 1000'
                    },
                    {
                        'has_tie': 'true',
                        'bag_weight_g': 'material_width_mm * height * thickness * density / 1000 + cord_weight_per_lm * cord_length / 1000'
                    },
                    {
                        'has_tie': '',
                        'bag_weight_g': 'material_width_mm * height * thickness * density / 1000'
                    }
                ]
            }
        },

        {
            'id': 't1c-packaging',
            'name': 'T1c Packaging Weights',
            'type': 'decisionTable',
            'content': {
                'hitPolicy': 'first',
                'inputs': [
                    {'id': 'packaging_mode', 'name': 'packaging_mode'}
                ],
                'outputs': [
                    {'id': 'roll_weight_kg',        'name': 'roll_weight_kg'},
                    {'id': 'box_weight_gross_kg',   'name': 'box_weight_gross_kg'},
                    {'id': 'pallet_weight_gross_kg','name': 'pallet_weight_gross_kg'},
                    {'id': 'bags_per_ton',          'name': 'bags_per_ton'}
                ],
                'rules': [
                    {
                        'packaging_mode': '"box_pallet"',
                        'roll_weight_kg':
                            'bags_per_roll * bag_weight_g / 1000 + roll_core_weight_per_lm * roll_core_length_m',
                        'box_weight_gross_kg':
                            'rolls_per_box * (bags_per_roll * bag_weight_g / 1000 + roll_core_weight_per_lm * roll_core_length_m) + box_tare_kg',
                        'pallet_weight_gross_kg':
                            'boxes_per_pallet * (rolls_per_box * (bags_per_roll * bag_weight_g / 1000 + roll_core_weight_per_lm * roll_core_length_m) + box_tare_kg) + pallet_tare_kg',
                        'bags_per_ton':
                            'if(bag_weight_g > 0, 1000000 / bag_weight_g, 0)'
                    },
                    {
                        'packaging_mode': '"roll_pallet"',
                        'roll_weight_kg':
                            'bags_per_roll * bag_weight_g / 1000 + roll_core_weight_per_lm * roll_core_length_m',
                        'box_weight_gross_kg':
                            '0',
                        'pallet_weight_gross_kg':
                            'rolls_per_pallet * (bags_per_roll * bag_weight_g / 1000 + roll_core_weight_per_lm * roll_core_length_m) + pallet_tare_kg',
                        'bags_per_ton':
                            'if(bag_weight_g > 0, 1000000 / bag_weight_g, 0)'
                    },
                    {
                        'packaging_mode': '"bulk_pallet"',
                        'roll_weight_kg': '0',
                        'box_weight_gross_kg': '0',
                        'pallet_weight_gross_kg': 'pallet_tare_kg',
                        'bags_per_ton':
                            'if(bag_weight_g > 0, 1000000 / bag_weight_g, 0)'
                    },
                    {
                        'packaging_mode': '',
                        'roll_weight_kg':
                            'bags_per_roll * bag_weight_g / 1000 + roll_core_weight_per_lm * roll_core_length_m',
                        'box_weight_gross_kg':
                            'rolls_per_box * (bags_per_roll * bag_weight_g / 1000 + roll_core_weight_per_lm * roll_core_length_m) + box_tare_kg',
                        'pallet_weight_gross_kg':
                            'boxes_per_pallet * (rolls_per_box * (bags_per_roll * bag_weight_g / 1000 + roll_core_weight_per_lm * roll_core_length_m) + box_tare_kg) + pallet_tare_kg',
                        'bags_per_ton':
                            'if(bag_weight_g > 0, 1000000 / bag_weight_g, 0)'
                    }
                ]
            }
        },

        {'id': 'zen_output', 'type': 'outputNode', 'name': 'Output'}
    ],
    'edges': [
        {'id': 'e1', 'sourceId': 'zen_input',    'targetId': 't1a-width'},
        {'id': 'e2', 'sourceId': 't1a-width',    'targetId': 't1b-weight'},
        {'id': 'e3', 'sourceId': 't1b-weight',   'targetId': 't1c-packaging'},
        {'id': 'e4', 'sourceId': 't1c-packaging','targetId': 'zen_output'}
    ]
}

{
    'nodes': [{
        'id': 't2-bags-ext',
        'name': 'T2 Materials',
        'type': 'decisionTable',
        'content': {
            'hitPolicy': 'collect',
            'inputs': [
                {'id': 'packaging_mode', 'name': 'packaging_mode'}
            ],
            'outputs': [
                {'id': 'material_role', 'name': 'material_role'},
                {'id': 'qty_expr',      'name': 'qty_expr'}
            ],
            'rules': [
                {
                    'packaging_mode': '',
                    'material_role': '"roll_core_kg"',
                    'qty_expr': '"roll_core_weight_per_lm * roll_core_length_m / bags_per_roll if bags_per_roll else 0"'
                },
                {
                    'packaging_mode': '"box_pallet"',
                    'material_role': '"box_tare_kg"',
                    'qty_expr': '"box_tare_kg / (bags_per_roll * rolls_per_box) if bags_per_roll and rolls_per_box else 0"'
                },
                {
                    'packaging_mode': '"box_pallet"',
                    'material_role': '"pallet_tare_kg"',
                    'qty_expr': '"pallet_tare_kg / (bags_per_roll * rolls_per_box * boxes_per_pallet) if bags_per_roll and rolls_per_box and boxes_per_pallet else 0"'
                },
                {
                    'packaging_mode': '"roll_pallet"',
                    'material_role': '"pallet_tare_kg"',
                    'qty_expr': '"pallet_tare_kg / (bags_per_roll * rolls_per_pallet) if bags_per_roll and rolls_per_pallet else 0"'
                }
            ]
        }
    }]
}

{
    'nodes': [{
        'id': 't3-bags-ext',
        'name': 'T3 Operations',
        'type': 'decisionTable',
        'content': {
            'hitPolicy': 'collect',
            'inputs': [
                {'id': 'inline_colors',     'name': 'inline_colors'},
                {'id': 'confection_colors', 'name': 'confection_colors'},
                {'id': 'has_tie',           'name': 'has_tie'},
                {'id': 'packaging_mode',    'name': 'packaging_mode'}
            ],
            'outputs': [
                {'id': 'operation',       'name': 'operation'},
                {'id': 'workcenter_code', 'name': 'workcenter_code'}
            ],
            'rules': [
                {
                    'inline_colors': '', 'confection_colors': '',
                    'has_tie': '', 'packaging_mode': '',
                    'operation': '"Extrusion"',
                    'workcenter_code': '"EXTR"'
                },
                {
                    'inline_colors': '', 'confection_colors': '',
                    'has_tie': '', 'packaging_mode': '',
                    'operation': '"Confection / Sealing"',
                    'workcenter_code': '"CONF"'
                },
                {
                    'inline_colors': '> 0', 'confection_colors': '',
                    'has_tie': '', 'packaging_mode': '',
                    'operation': '"Flexo Print (Inline)"',
                    'workcenter_code': '"PRINT_INLINE"'
                },
                {
                    'inline_colors': '', 'confection_colors': '> 0',
                    'has_tie': '', 'packaging_mode': '',
                    'operation': '"Flexo Print (Confection)"',
                    'workcenter_code': '"PRINT_CONF"'
                },
                {
                    'inline_colors': '', 'confection_colors': '',
                    'has_tie': 'true', 'packaging_mode': '',
                    'operation': '"Cord / Drawtape Insertion"',
                    'workcenter_code': '"CORD"'
                },
                {
                    'inline_colors': '', 'confection_colors': '',
                    'has_tie': '', 'packaging_mode': '"box_pallet"',
                    'operation': '"Packaging — Box + Pallet"',
                    'workcenter_code': '"PKG"'
                },
                {
                    'inline_colors': '', 'confection_colors': '',
                    'has_tie': '', 'packaging_mode': '"roll_pallet"',
                    'operation': '"Packaging — Roll + Pallet"',
                    'workcenter_code': '"PKG"'
                },
                {
                    'inline_colors': '', 'confection_colors': '',
                    'has_tie': '', 'packaging_mode': '"bulk_pallet"',
                    'operation': '"Packaging — Bulk Pallet"',
                    'workcenter_code': '"PKG"'
                }
            ]
        }
    }]
}
